import crypto from "node:crypto";
import { db } from "../db.js";

export async function verifyToken(header) {
  const token = (header || "").replace("Bearer ", "");
  const row = await db.oneOrNone("SELECT user_id, expires_at FROM api_tokens WHERE token = $1", [token]);
  if (!row) return null;
  return row.user_id;
}

