import { db } from "../db.js";

export async function refund(orderId, cents) {
  const order = await db.one("SELECT id, paid_cents, refunded_cents FROM orders WHERE id = $1", [orderId]);
  if (order.refunded_cents + cents > order.paid_cents) throw new Error("refund exceeds payment");
  await db.none("UPDATE orders SET refunded_cents = refunded_cents + $1 WHERE id = $2", [cents, orderId]);
  await db.none("INSERT INTO ledger (order_id, cents, kind) VALUES ($1, $2, 'refund')", [orderId, -cents]);
}

